describe('the month picker a statement asks for', () => {
  beforeAll(() => {
    jest.useFakeTimers({ now: new Date(2026, 9, 20, 9, 0) });
  });
  afterAll(() => {
    jest.useRealTimers();
  });
  it('shows the stored month as words, offers no future month, and reports the month\'s last day', () => {
    const onChange = jest.fn();
    const c = mount(<DateField testID="stmt" value="2026-03-31" monthPicker="end" placeholder="Statement month" onChange={onChange} />);
    expect(c.json()).toContain('March 2026');
    c.press(c.tree.root.findAll((n) => typeof n.props?.onPress === 'function', { deep: true })[0]!);
    expect(c.byLabel('Next year').props.disabled).toBe(true);
    const months = () => onePerPress(c.tree.root.findAll((n) => typeof n.props?.onPress === 'function' && n.props?.accessibilityState?.selected !== undefined, { deep: true }));
    expect(months().filter((m) => m.props.disabled).length).toBe(2);
    c.press(c.byLabel('Previous year'));
    expect(months().some((m) => m.props.disabled)).toBe(false);
    c.press(months()[10]!);
    c.press(c.byText('Next'));
    expect(onChange).toHaveBeenCalledWith('2025-11-30');
    c.unmount();
  });
  it('reports the first day for a start month, and Cancel closes without choosing', () => {
    const onChange = jest.fn();
    const c = mount(<DateField testID="from" monthPicker="start" placeholder="From" onChange={onChange} />);
    expect(c.json()).toContain('From');
    const open = () => c.press(c.tree.root.findAll((n) => typeof n.props?.onPress === 'function', { deep: true })[0]!);
    open();
    c.press(c.byText('Cancel'));
    expect(onChange).not.toHaveBeenCalled();
    open();
    const months = onePerPress(c.tree.root.findAll((n) => typeof n.props?.onPress === 'function' && n.props?.accessibilityState?.selected !== undefined, { deep: true }));
    c.press(months[0]!);
    c.press(c.byText('Next'));
    expect(onChange).toHaveBeenCalledWith('2026-01-01');
    c.unmount();
  });
});
